def generate_sequence(g1, g2, g3, g4, max_terms=10):
    g = [g1, g2, g3, g4]

    # Helper function to check validity
    def is_valid(x):
        return isinstance(x, int) and x >= 2

    # Check initial conditions immediately
    if not all(is_valid(x) for x in g):
        return None, "Initial condition invalid"

    # Calculate subsequent terms using the derived relation
    # g(n+4) = g(n+2) - (g(n) - g(n+2)) / g(n+3)
    # Indices in Python list (0-based): g[i+4] = g[i+2] - (g[i] - g[i+2]) / g[i+3]

    for k in range(1, max_terms - 4): # We need to calculate up to g[9] (k=1 to 5)
        i = k - 1 # i = 0 when calculating g[4]

        # Ensure enough elements exist for the calculation (i+3 must be valid)
        if i + 3 >= len(g):
            break

        try:
            # g[i+4] corresponds to g(n+4) when starting from n=i+1
            numerator = g[i] - g[i+2]
            denominator = g[i+3]

            if denominator == 0:
                return None, "Division by zero encountered"

            # The resulting term must be an integer
            if numerator % denominator != 0:
                return None, "Sequence term is not an integer"

            next_g = g[i+2] - (numerator // denominator)

            if not is_valid(next_g):
                return None, "Sequence term < 2 or invalid"

            g.append(next_g)

        except Exception as e:
            return None, f"Calculation error: {e}"

    # Truncate to the first 10 terms (length 10)
    return g[:10], None

test_cases = [
    (2, 2, 2, 2), # Case 1: All minimal
    (5, 5, 5, 5), # Case 2: All maximal (in [2, 5])
    (2, 5, 2, 5), # Case 3: Alternating
    (3, 4, 3, 4)  # Case 4: Other mixed values
]

results = {}
for g1, g2, g3, g4 in test_cases:
    sequence, error = generate_sequence(g1, g2, g3, g4)
    results[(g1, g2, g3, g4)] = (sequence, error)

print("--- Test Results ---")
for case, (seq, err) in results.items():
    if err:
        print(f"Initial conditions {case}: Failed ({err})")
    else:
        print(f"Initial conditions {case}: Sequence = {seq}")
